/**
 * Affiliate disclosure line — required by FinlyWealth Affiliate Agreement
 * section 11 to appear BEFORE the first affiliate link on every page, post
 * and email where we share one. A footnote at the bottom, or a line in the
 * About page, does not satisfy the agreement.
 *
 * Copy is the "Plain" / "We" template generated by the FinlyWealth hub's
 * disclosure chooser (finlywealth.com/affiliate-hub/disclosures), chosen
 * because AirportLounges.ca speaks as a brand, not a single author.
 *
 * Variants:
 *   - 'inline'   — one subtle line in champagne-glint; default for article
 *                  bodies, airport hub pages, lounge detail pages.
 *   - 'callout'  — boxed with info icon; use once per page at the top when
 *                  the whole page is affiliate-heavy (credit card comparison
 *                  pages, blog posts with many partner links).
 *   - 'footer'   — muted bottom-of-sidebar version where a visible inline
 *                  disclosure already appears elsewhere above the fold.
 */

type Variant = 'inline' | 'callout' | 'footer'

interface Props {
  variant?: Variant
  mentionsRebate?: boolean
}

const BASE_COPY =
  'Disclosure: This page contains affiliate links. If you apply through them, we may earn a commission from FinlyWealth, at no cost to you. Product details and offers change often and may be out of date here, so confirm the current terms with the issuer before you apply.'

// FinlyWealth-required additional line when a page discusses cash rebates,
// so readers know the rebate is paid by FinlyWealth, not the bank.
const REBATE_LINE =
  ' Cash rebates are paid by FinlyWealth, not by the bank or card issuer, and have their own terms.'

export default function AffiliateDisclosure({
  variant = 'inline',
  mentionsRebate = false,
}: Props) {
  const copy = BASE_COPY + (mentionsRebate ? REBATE_LINE : '')

  if (variant === 'callout') {
    return (
      <aside
        role="note"
        aria-label="Affiliate disclosure"
        className="not-prose my-6 bg-champagne-glint/60 border-l-4 border-sand-dark p-4 md:p-5 text-sm text-on-surface-variant leading-relaxed"
      >
        <div className="flex items-start gap-3">
          <span
            className="material-symbols-outlined text-sand-dark shrink-0"
            style={{ fontSize: '20px' }}
          >
            info
          </span>
          <p>{copy}</p>
        </div>
      </aside>
    )
  }

  if (variant === 'footer') {
    return (
      <p className="text-[11px] text-secondary/70 leading-relaxed italic mt-6">
        {copy}
      </p>
    )
  }

  // inline (default)
  return (
    <p className="not-prose my-4 text-xs text-on-surface-variant leading-relaxed bg-champagne-glint/40 border-l-2 border-sand-dark/40 px-4 py-3">
      <span className="font-label-caps text-[9px] uppercase tracking-widest text-sand-dark block mb-1">
        Disclosure
      </span>
      {copy.replace(/^Disclosure: /, '')}
    </p>
  )
}
